1	"use client";
2	
3	import { useMemo, useRef, useState } from "react";
4	import { useActionState, useEffect } from "react";
5	import { payAndDeploy } from "@/lib/actions";
6	import { AppLogo } from "@/components/ui/AppLogo";
7	import { VersionPickerModal, type FamilyGroup } from "@/components/customer/VersionPickerModal";
8	import { VPS_TERMS, vpsTermPriceCents, vpsEffectiveMonthly } from "@/lib/billing-terms";
9	import { walletSplit } from "@/lib/wallet-split";
10	import {
11	  EXTRA_DISK_MAX_ADD_GB,
12	  EXTRA_DISK_MIN_GB,
13	  EXTRA_DISK_ONE_WAY_NOTE,
14	  EXTRA_DISK_STEP_GB,
15	  effectiveDiskGB,
16	  extraDiskCentsAt,
17	} from "@/lib/extra-disk";
18	
19	type Plan = {
20	  id: string; name: string; cpuCores: number; ramMB: number; diskGB: number;
21	  bandwidthTB: number; priceCents: number; storageTier: string;
22	};
23	type Image = {
24	  id: string; slug: string; name: string; category: string; family: string;
25	  version: string; logo: string; minRamMB: number; minDiskGB: number;
26	  licenseRequired: boolean; featured: boolean;
27	};
28	type NodeOpt = { id: string; name: string; publicIp: string };
29	
30	const money = (c: number) => `$${(c / 100).toFixed(2)}`;
31	
32	/** APPLICATION-category images with one of these families are split into the Games tab. */
33	const GAME_FAMILIES = new Set(["minecraft", "valheim", "rust", "palworld", "cs2", "terraria"]);
34	
35	/** Install-step tabs. Games are peeled out of Applications into their own tab. */
36	const TABS = [
37	  { key: "os", label: "Operating Systems", match: (i: Image) => i.category === "PLAIN_OS" },
38	  { key: "panels", label: "Control Panels", match: (i: Image) => i.category === "CONTROL_PANEL" },
39	  { key: "apps", label: "Applications", match: (i: Image) => i.category === "APPLICATION" && !GAME_FAMILIES.has(i.family) },
40	  { key: "games", label: "Games", match: (i: Image) => i.category === "APPLICATION" && GAME_FAMILIES.has(i.family) },
41	] as const;
42	
43	const OS_FAMILY_NAMES: Record<string, string> = {
44	  ubuntu: "Ubuntu", debian: "Debian", almalinux: "AlmaLinux", rocky: "Rocky Linux",
45	  fedora: "Fedora", centos: "CentOS", arch: "Arch Linux", alpine: "Alpine", kali: "Kali Linux", opensuse: "openSUSE",
46	};
47	/** Clean family display name (no version) for the OS family cards. */
