3	import { SANDBOX, sandboxIp, sandboxMac } from "./sandbox";
4	import { getSettingInt } from "./settings";
5	
6	const SERVER = process.env.OVH_SERVER_NAME ?? "ns5002569.ip-51-79-162.net";
7	/**
8	 * Fallback monthly price for a dedicated IPv4. Defaults to 0 — a dedicated IP is
9	 * INCLUDED on every plan (its cost is folded into plan pricing, as the marketing
10	 * pages state). The admin `dedicated_ip_price_cents` setting is the source of
11	 * truth; use `dedicatedIpMonthlyCents()` in billing paths, not this constant.
12	 */
13	export const DEDICATED_IP_PRICE_CENTS = Number(process.env.DEDICATED_IP_PRICE_CENTS ?? 0);
14	
15	/**
16	 * The monthly dedicated-IP surcharge actually charged, from the admin setting
17	 * (`dedicated_ip_price_cents`, default 0 = included). Single source of truth for
18	 * every order/renewal/display path so they can never disagree.
19	 */
20	export async function dedicatedIpMonthlyCents(): Promise<number> {
21	  return getSettingInt("dedicated_ip_price_cents", DEDICATED_IP_PRICE_CENTS);
22	}
23	/** Keep this many spare IPs in the pool; auto-order/release aims to stay near it. */
24	export const DEDICATED_IP_BUFFER = Number(process.env.DEDICATED_IP_BUFFER ?? 2);
25	
26	/** OVH failover gateway = the host's /24 gateway (…​.254). */
27	export function ovhGateway(): string {
28	  const ip = process.env.PUBLIC_IP ?? "51.79.162.96";
29	  const parts = ip.split(".");
30	  return `${parts[0]}.${parts[1]}.${parts[2]}.254`;
31	}
32	
33	/**
34	 * Pull additional/failover IPv4 addresses routed to our server from OVH and
35	 * upsert them into the pool. The host's own primary IP is never poolable.
36	 */
37	export async function syncDedicatedIpPool(): Promise<{ imported: number; total: number }> {
38	  if (SANDBOX) return { imported: 0, total: 0 };
39	  if (!ovhConfigured()) return { imported: 0, total: 0 };
40	  const primary = process.env.PUBLIC_IP;
41	  const blocks: string[] = await ovhApi.ips();
42	  let imported = 0;
43	  for (const block of blocks) {
44	    if (block.includes(":")) continue; // IPv6 handled separately
45	    let info: any;
46	    try {
47	      info = await ovhApi.ipInfo(block);
48	    } catch {
49	      continue;
50	    }
51	    if (info?.routedTo?.serviceName !== SERVER) continue;
52	    if (info?.type !== "failover" && info?.type !== "additional") continue; // exclude the primary "dedicated" host IP
53	    // A /32 block is a single usable IP == the block minus the mask.
54	    const address = block.split("/")[0];
55	    if (address === primary) continue;
56	    const existing = await db.dedicatedIp.findUnique({ where: { address } });
57	    if (!existing) {
58	      await db.dedicatedIp.create({ data: { address, ovhBlock: block, status: "FREE" } });
59	      imported++;
60	    }
61	  }
62	  const total = await db.dedicatedIp.count();
63	  return { imported, total };
64	}
65	
66	export async function freeCount(): Promise<number> {
67	  return db.dedicatedIp.count({ where: { status: "FREE" } });
68	}
