70	/** Find the OVH Virtual MAC currently bound to an IP, if any. */
71	async function findVirtualMacForIp(address: string): Promise<string | null> {
72	  const macs: string[] = await ovh("GET", `/dedicated/server/${SERVER}/virtualMac`).catch(() => []);
73	  for (const m of macs) {
74	    const ips: string[] = await ovh(
75	      "GET",
76	      `/dedicated/server/${SERVER}/virtualMac/${m}/virtualAddress`
77	    ).catch(() => []);
78	    if (ips.includes(address)) return m;
79	  }
80	  return null;
81	}
82	
83	/**
84	 * Claim a free IP for a server and create its OVH Virtual MAC so the VM can use it.
85	 * Returns the address + virtualMac + gateway, or null if none available.
86	 */
87	export async function allocateDedicatedIp(
88	  serverId: string,
89	  vmid: number
90	): Promise<{ address: string; virtualMac: string; gateway: string } | null> {
91	  if (SANDBOX) {
92	    // Hand out a synthetic dedicated IP without any OVH call or pool mutation.
93	    return { address: sandboxIp(vmid), virtualMac: sandboxMac(vmid), gateway: "198.51.100.254" };
94	  }
95	  // Idempotent per server: PROVISION can retry (up to MAX_ATTEMPTS). If this
96	  // server already holds a fully-allocated dedicated IP (ASSIGNED + a bound
97	  // Virtual MAC), return it instead of claiming a second pool IP — re-claiming
98	  // would leak an IP and P2002 on the unique DedicatedIp.serverId.
99	  const mine = await db.dedicatedIp.findUnique({ where: { serverId } });
100	  if (mine && mine.status === "ASSIGNED" && mine.virtualMac) {
101	    return { address: mine.address, virtualMac: mine.virtualMac, gateway: ovhGateway() };
102	  }
103	  if (!ovhConfigured()) return null;
104	  // Atomically claim a FREE ip
105	  const claim = await db.$transaction(async (tx) => {
106	    const ip = await tx.dedicatedIp.findFirst({ where: { status: "FREE" }, orderBy: { createdAt: "asc" } });
107	    if (!ip) return null;
108	    await tx.dedicatedIp.update({ where: { id: ip.id }, data: { status: "PENDING", serverId } });
109	    return ip;
110	  });
111	  if (!claim) return null;
112	
113	  try {
114	    // Reuse an existing vMAC for this IP if one is already bound; else create one.
115	    let mac = await findVirtualMacForIp(claim.address);
116	    if (!mac) {
117	      // Creation is asynchronous (returns a task) — kick it off then poll.
118	      await ovhApi.createVirtualMac(SERVER, claim.address, `nxeon-${vmid}`);
119	      for (let i = 0; i < 40 && !mac; i++) {
120	        await new Promise((r) => setTimeout(r, 3000));
121	        mac = await findVirtualMacForIp(claim.address);
122	      }
123	    }
124	    if (!mac) throw new Error("Virtual MAC not bound after creation (OVH task still pending)");
125	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED", virtualMac: mac } });
126	    return { address: claim.address, virtualMac: mac, gateway: ovhGateway() };
127	  } catch (e) {
128	    // Roll the claim back to FREE on failure
129	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "FREE", serverId: null, virtualMac: null } });
130	    throw e;
131	  }
132	}
133	
134	/** Release a server's dedicated IP back to the pool (deletes the OVH Virtual MAC). */
135	export async function releaseDedicatedIp(serverId: string): Promise<void> {
136	  if (SANDBOX) return;
137	  const ip = await db.dedicatedIp.findUnique({ where: { serverId } });
138	  if (!ip) return;
139	  if (ovhConfigured() && ip.virtualMac) {
140	    try {
141	      // Remove the IP from the vMAC, then delete the vMAC.
142	      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}/virtualAddress/${ip.address}`).catch(() => {});
143	      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}`).catch(() => {});
144	    } catch {
145	      /* best-effort */
146	    }
147	  }
148	  await db.dedicatedIp.update({
149	    where: { id: ip.id },
150	    data: { status: "FREE", serverId: null, virtualMac: null },
151	  });
152	}
153	
154	/** Set reverse DNS (PTR) for a dedicated IP. */
155	export async function setDedicatedReverse(address: string, reverse: string): Promise<void> {
156	  if (!ovhConfigured()) return;
157	  await ovhApi.setReverse(`${address}/32`, address, reverse);
158	  await db.dedicatedIp.updateMany({ where: { address }, data: { reverse } });
159	}
