186	/**
187	 * Credit a user's wallet for a completed Checkout session, idempotently.
188	 * Called from both the success-redirect confirm route (works without HTTPS)
189	 * and the webhook (belt-and-suspenders once HTTPS is available).
190	 * Returns true if a credit was applied this call.
191	 */
192	export async function creditCheckoutSession(sessionId: string): Promise<boolean> {
193	  const session = await stripe().checkout.sessions.retrieve(sessionId);
194	  const userId = session.metadata?.nxeonUserId;
195	  const cents = session.amount_total ?? 0;
196	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
197	
198	  // Legacy guard: rows credited before `stripeSessionId` existed only recorded the
199	  // session id inside the description.
200	  const legacy = await db.walletTransaction.findFirst({
201	    where: { stripeSessionId: null, description: { contains: session.id } },
202	  });
203	  if (legacy) return false;
204	
205	  // Idempotency is enforced by the UNIQUE index on `stripeSessionId` — NOT by a
206	  // read-then-write check. The confirm-redirect and the webhook can arrive
207	  // concurrently (and /api/stripe/confirm is unauthenticated and replayable), so
208	  // only the database can safely decide the winner. P2002 == already credited.
209	  try {
210	    await db.$transaction([
211	      db.walletTransaction.create({
212	        data: {
213	          userId,
214	          amountCents: cents,
215	          description: `Stripe payment (${session.id})`,
216	          stripeSessionId: session.id,
217	        },
218	      }),
219	      db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
220	      db.notification.create({
221	        data: {
222	          userId,
223	          title: `Payment of $${(cents / 100).toFixed(2)} received`,
224	          href: "/dashboard/billing",
225	        },
226	      }),
227	      // PAID invoice for the top-up. Created in the SAME guarded transaction as
228	      // the wallet credit, so the UNIQUE(stripeSessionId) constraint that makes
229	      // the credit idempotent also prevents a duplicate invoice on replay.
230	      db.invoice.create({
231	        data: invoiceCreateData({
232	          userId,
233	          description: "Wallet top-up",
234	          status: "PAID",
235	          lineItems: [
236	            { description: "Wallet top-up", qty: 1, unitCents: cents, amountCents: cents },
237	          ],
238	        }),
239	      }),
240	    ]);
241	  } catch (e) {
242	    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
243	    throw e;
244	  }
245	  // A funded wallet is the referred user's first paid action — reward both sides.
246	  try {
247	    const { maybeRewardReferral } = await import("./actions-growth");
248	    await maybeRewardReferral(userId);
249	  } catch { /* best-effort */ }
250	  try {
251	    const u = await db.user.findUnique({ where: { id: userId } });
252	    if (u) {
253	      const { sendMail, emails } = await import("./mailer");
254	      const tpl = emails.receipt(`$${(cents / 100).toFixed(2)}`, "wallet top-up");
255	      // `kind` + `userId` hands this to the preference policy in lib/prefs.ts.
256	      // A receipt is ACCOUNT tier — suppressible by email if the customer turned
257	      // account email off. This is the one send site where that toggle actually
258	      // bites today, so it is the one that made the switch a lie.
259	      await sendMail({ to: u.email, subject: tpl.subject, html: tpl.html, userId, kind: "receipt" });
260	    }
261	  } catch { /* best-effort */ }
262	  return true;
263	}
