18	export function ResizeDown({
19	  serverId,
20	  currentPlanId,
21	  currentDiskGB,
22	  currentPriceCents,
23	  termMonths,
24	  expiresAt,
25	  isFree,
26	  plans,
27	  disabled,
28	}: {
29	  serverId: string;
30	  currentPlanId: string;
31	  currentDiskGB: number;
32	  currentPriceCents: number;
33	  termMonths: number;
34	  /** ISO string of the current term end, or null */
35	  expiresAt: string | null;
36	  isFree: boolean;
37	  plans: PlanRow[];
38	  disabled?: boolean;
39	}) {
40	  const [selected, setSelected] = useState<string | null>(null);
41	  const [error, setError] = useState<string | null>(null);
42	  const [pending, start] = useTransition();
43	
44	  // A downgrade candidate must be cheaper AND keep the disk at least as large.
45	  //
46	  // Filtering on price alone offered targets that could NEVER succeed: a disk
47	  // cannot shrink on the hypervisor, so `resizeServerDown` refuses any plan with a
48	  // smaller disk — and in the live catalogue every cheaper plan HAS a smaller disk
49	  // (Starter 25GB / Standard 50GB / Pro 80GB / Max 120GB), which makes the number
50	  // of viable downgrades exactly ZERO. Customers were shown a list of options and
51	  // every single one errored. The guard is correct; offering the action was the bug.
52	  const smaller = plans.filter(
53	    (p) => p.id !== currentPlanId && p.priceCents < currentPriceCents && p.diskGB >= currentDiskGB
54	  );
55	  // Cheaper plans that exist but are blocked purely by the disk rule — used to
56	  // explain WHY there is nothing to choose, instead of showing an empty box.
57	  const blockedByDisk = plans.filter(
58	    (p) => p.id !== currentPlanId && p.priceCents < currentPriceCents && p.diskGB < currentDiskGB
59	  );
60	  const target = smaller.find((p) => p.id === selected) ?? null;
61	
62	  // Prorated credit from the SAME shared function the server credits with
63	  // (lib/proration.ts), not a local reimplementation. The previous copy priced off
64	  // undiscounted list price over its own notion of the remaining fraction, so what
65	  // the customer saw could drift from what they were credited — the same class of
66	  // divergence that let the upgrade side overcharge by $379.
67	  function estimateCredit(newPriceCents: number): number {
68	    if (isFree || !expiresAt) return 0;
69	    return prorateDowngradeCreditCents({
70	      fromMonthlyCents: currentPriceCents,
71	      toMonthlyCents: newPriceCents,
72	      termMonths,
73	      monthsRemaining: remainingMonths(new Date(expiresAt), Date.now()),
