92	        <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
93	          {error}
94	        </div>
95	      )}
96	
97	      {smaller.length === 0 ? (
98	        // Two genuinely different reasons for an empty list, and conflating them
99	        // told most customers something false. "You're on the smallest plan" is
100	        // only true when no cheaper plan exists at all; the common case is that
101	        // cheaper plans DO exist but every one has a smaller disk, and a disk
102	        // cannot shrink. Saying which it is means the customer knows whether to
103	        // wait, contact support, or stop looking.
104	        blockedByDisk.length > 0 ? (
105	          <div className="rounded-xl border border-amber-500/30 bg-amber-500/[0.06] px-4 py-3 text-sm">
106	            <p className="font-medium text-amber-300">No self-service downgrade available</p>
107	            <p className="mt-1 text-slate-400">
108	              Cheaper plans exist, but each one has a smaller disk than your current{" "}
109	              {currentDiskGB} GB — and a server&apos;s disk can&apos;t be shrunk without
110	              destroying data, so we won&apos;t do it automatically.{" "}
111	              <a
112	                href="/dashboard/support"
113	                className="text-brand-300 underline decoration-brand-500/40 underline-offset-2 hover:text-brand-200"
114	              >
115	                Contact support
116	              </a>{" "}
117	              and we&apos;ll move you across manually, keeping your data.
118	            </p>
119	          </div>
120	        ) : (
121	          <p className="text-sm text-slate-400">
122	            You&apos;re already on the smallest plan — there&apos;s nothing smaller to move to.
123	          </p>
124	        )
125	      ) : (
126	        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
127	          {smaller.map((p) => {
128	            const diskShrinks = p.diskGB < currentDiskGB;
129	            const active = selected === p.id;
130	            return (
131	              <button
132	                key={p.id}
133	                type="button"
134	                disabled={diskShrinks || pending || disabled}
135	                title={
136	                  diskShrinks
137	                    ? `Disk can't shrink — this plan has ${p.diskGB} GB, your server uses a ${currentDiskGB} GB disk.`
138	                    : undefined
139	                }
140	                onClick={() => setSelected(active ? null : p.id)}
141	                className={`card p-4 text-left transition-all ${
142	                  diskShrinks
143	                    ? "cursor-not-allowed opacity-40"
144	                    : active
145	                      ? "cursor-pointer border-accent-blue ring-1 ring-accent-blue"
146	                      : "cursor-pointer hover:border-white/20"
147	                }`}
148	              >
149	                <div className="flex items-baseline justify-between">
150	                  <span className="font-semibold">{p.name}</span>
151	                  <span className="text-lg font-bold">
