153	                    <span className="text-xs font-normal text-slate-400">/mo</span>
154	                  </span>
155	                </div>
156	                <p className="mt-1 text-sm text-slate-400">
157	                  {p.cpuCores} vCPU · {p.ramMB / 1024} GB RAM · {p.diskGB} GB NVMe · {p.bandwidthTB} TB
158	                </p>
159	                {diskShrinks && (
160	                  <p className="mt-2 text-xs text-slate-500">Smaller disk — can&apos;t shrink</p>
161	                )}
162	              </button>
163	            );
164	          })}
165	        </div>
166	      )}
167	
168	      {smaller.length > 0 && (
169	        <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3">
170	          <p className="text-xs text-slate-400">
171	            {target && credit > 0 ? (
172	              <>
173	                Estimated credit back to your wallet:{" "}
174	                <span className="font-semibold text-emerald-400">{fmtMoney(credit)}</span>. Requires a
175	                power cycle.
176	              </>
177	            ) : (
178	              "Downsizing requires a power cycle. The new price applies at your next renewal."
179	            )}
180	          </p>
181	          <button
182	            className="btn-primary"
183	            disabled={!target || pending || disabled}
184	            onClick={() => {
185	              if (!target) return;
186	              if (
187	                !window.confirm(
188	                  `Downsize this server to ${target.name} (${fmtMoney(target.priceCents)}/mo)?${
189	                    credit > 0 ? ` ${fmtMoney(credit)} will be credited to your wallet.` : ""
190	                  } The server will be power-cycled.`
191	                )
192	              )
193	                return;
194	              start(async () => {
195	                setError(null);
196	                const res = await resizeServerDown(serverId, target.id);
197	                if (res?.error) setError(res.error);
198	                else setSelected(null);
199	              });
200	            }}
201	          >
202	            {pending ? "Downsizing…" : target ? `Downsize to ${target.name}` : "Select a plan"}
203	          </button>
