1	import { db } from "@/lib/db";
2	import { getSetting, SETTINGS_DEFAULTS } from "@/lib/settings";
3	import type { Invoice, InvoiceStatus, Prisma, User } from "@prisma/client";
4	
5	/**
6	 * Seller identity + number prefix printed on an invoice, resolved from Settings →
7	 * General/Billing. Read once per render and handed to the (synchronous) renderer.
8	 */
9	export type InvoiceBranding = {
10	  /** `invoice_prefix`, never blank — see `invoiceBranding()`. */
11	  numberPrefix: string;
12	  /** `brand_name`, never blank. */
13	  brandName: string;
14	  /** `company_legal_name` — "" means "omit the seller block". */
15	  legalName: string;
16	  /** `company_address` — "" means "omit the seller address". */
17	  address: string;
18	};
19	
20	const FALLBACK_BRANDING: InvoiceBranding = {
21	  numberPrefix: SETTINGS_DEFAULTS.invoice_prefix,
22	  brandName: SETTINGS_DEFAULTS.brand_name,
23	  legalName: "",
24	  address: "",
25	};
26	
27	/**
28	 * Read the invoice branding from Settings.
29	 *
30	 * `numberPrefix` is forced non-empty. `Invoice.number` is a bare autoincrement, so an
31	 * operator who clears the field would otherwise produce documents identified only as
32	 * "00012" — not quotable to a customer, not greppable in a mailbox, and impossible to
33	 * tell apart from a server ID or an order number in a support thread.
34	 *
35	 * `legalName`/`address` stay blank-able by design: the seller block is omitted entirely
36	 * when they are unset, rather than printing an empty "From" heading. That is why the
37	 * "shown on invoices" claim on the admin field is now true without the panel having to
38	 * demand a value it does not have.
39	 */
40	export async function invoiceBranding(): Promise<InvoiceBranding> {
41	  const [prefix, brandName, legalName, address] = await Promise.all([
42	    getSetting("invoice_prefix"),
43	    getSetting("brand_name"),
44	    getSetting("company_legal_name"),
45	    getSetting("company_address"),
46	  ]);
47	  return {
48	    numberPrefix: prefix.trim() || SETTINGS_DEFAULTS.invoice_prefix,
49	    brandName: brandName.trim() || SETTINGS_DEFAULTS.brand_name,
50	    legalName: legalName.trim(),
51	    address: address.trim(),
52	  };
53	}
54	
55	/**
56	 * The customer-facing invoice identifier: the configured prefix plus the zero-padded
57	 * autoincrement (`INV-00012`).
58	 *
59	 * One function so every surface agrees. The padding was previously duplicated as
60	 * `#${String(n).padStart(5, "0")}` at eight call sites, which is precisely why
61	 * `invoice_prefix` had no reader — there was no single place to wire it. The `#` sigil
62	 * is dropped now that a prefix is always present; keeping both would render `#INV-00012`.
63	 */
64	export function formatInvoiceNumber(
65	  number: number,
66	  prefix: string = SETTINGS_DEFAULTS.invoice_prefix,
67	): string {
68	  return `${prefix}${String(number).padStart(5, "0")}`;
69	}
70	
71	/**
72	 * Invoice line item shape stored in `Invoice.lineItems` (Json).
73	 * Amounts are integer cents. `amountCents` is authoritative; qty * unitCents
74	 * is used as a fallback when a line omits it.
75	 */
76	export type LineItem = {
77	  description: string;
78	  qty: number;
79	  unitCents: number;
80	  amountCents: number;
81	};
82	
83	export function coerceLineItems(raw: unknown): LineItem[] {
84	  if (!Array.isArray(raw)) return [];
85	  return raw
86	    .filter((x): x is Record<string, unknown> => !!x && typeof x === "object")
87	    .map((x) => {
88	      const qty = Number(x.qty ?? 1) || 0;
89	      const unitCents = Math.round(Number(x.unitCents ?? 0) || 0);
90	      const amountCents = Math.round(
91	        Number(x.amountCents ?? qty * unitCents) || 0
92	      );
93	      return {
94	        description: String(x.description ?? "Item"),
95	        qty,
96	        unitCents,
97	        amountCents,
98	      };
99	    });
100	}
101	
102	/** Compute subtotal / tax / total (all integer cents) for an invoice. */
103	export function invoiceTotals(invoice: Pick<Invoice, "lineItems" | "taxCents" | "amountCents">) {
104	  const items = coerceLineItems(invoice.lineItems);
105	  const subtotalCents = items.reduce((sum, li) => sum + li.amountCents, 0);
106	  const taxCents = invoice.taxCents ?? 0;
107	  // `amountCents` is the stored authoritative total; fall back to computed.
108	  const totalCents = invoice.amountCents ?? subtotalCents + taxCents;
109	  return { items, subtotalCents, taxCents, totalCents };
110	}
111	
112	const STATUS_LABEL: Record<InvoiceStatus, string> = {
113	  OPEN: "Open",
114	  PAID: "Paid",
115	  VOID: "Void",
116	  REFUNDED: "Refunded",
117	};
118	
119	export function invoiceStatusLabel(status: InvoiceStatus): string {
120	  return STATUS_LABEL[status] ?? status;
121	}
122	
123	export type InvoiceInput = {
124	  userId: string;
125	  description: string;
126	  lineItems: LineItem[];
127	  taxCents?: number;
128	  status?: InvoiceStatus;
129	  period?: { start?: Date | null; end?: Date | null };
130	};
131	
132	/**
133	 * Build the `data` payload for an Invoice row WITHOUT touching the database, so
134	 * a charge site can create the invoice inside its own guarded `$transaction`
135	 * (sharing the charge's idempotency guard) via `tx.invoice.create({ data })`.
136	 * The stored total (`amountCents`) is always derived from line items + tax so
137	 * callers can't desync the stamped total from the itemised breakdown.
138	 */
139	export function invoiceCreateData(opts: InvoiceInput): Prisma.InvoiceUncheckedCreateInput {
140	  const items = opts.lineItems.map((li) => ({
141	    description: String(li.description),
142	    qty: Number(li.qty) || 0,
143	    unitCents: Math.round(Number(li.unitCents) || 0),
144	    amountCents: Math.round(
145	      Number(li.amountCents ?? (Number(li.qty) || 0) * (Number(li.unitCents) || 0)) || 0
146	    ),
147	  }));
148	  const taxCents = Math.round(opts.taxCents ?? 0);
149	  const subtotalCents = items.reduce((s, li) => s + li.amountCents, 0);
150	  const amountCents = subtotalCents + taxCents;
151	  const status = opts.status ?? "OPEN";
152	
153	  return {
154	    userId: opts.userId,
155	    description: opts.description,
156	    lineItems: items,
157	    taxCents,
158	    amountCents,
159	    status,
160	    paidAt: status === "PAID" ? new Date() : null,
161	    periodStart: opts.period?.start ?? null,
162	    periodEnd: opts.period?.end ?? null,
163	  };
164	}
165	
166	/**
167	 * Create an Invoice row directly. The total (`amountCents`) is derived from the
168	 * line items plus tax so callers can't accidentally desync the stamped total
169	 * from the itemised breakdown.
170	 */
171	export async function createInvoice(opts: InvoiceInput): Promise<Invoice> {
172	  return db.invoice.create({ data: invoiceCreateData(opts) });
173	}
174	
175	function esc(s: unknown): string {
176	  return String(s ?? "")
177	    .replace(/&/g, "&amp;")
178	    .replace(/</g, "&lt;")
179	    .replace(/>/g, "&gt;")
180	    .replace(/"/g, "&quot;");
181	}
182	
183	function money(cents: number): string {
184	  const neg = cents < 0;
185	  return `${neg ? "−" : ""}$${(Math.abs(cents) / 100).toFixed(2)}`;
186	}
187	
188	function fmtDate(d: Date | null | undefined): string {
189	  if (!d) return "—";
190	  return new Date(d).toLocaleDateString("en-US", {
191	    year: "numeric",
192	    month: "short",
193	    day: "numeric",
194	  });
195	}
196	
197	const STATUS_STAMP: Record<InvoiceStatus, { color: string; label: string }> = {
198	  PAID: { color: "#10b981", label: "PAID" },
199	  OPEN: { color: "#f59e0b", label: "OPEN" },
200	  VOID: { color: "#64748b", label: "VOID" },
201	  REFUNDED: { color: "#8a70fb", label: "REFUNDED" },
202	};
203	
204	/**
205	 * Render a clean, print-ready branded HTML invoice. Intended to be served
206	 * standalone (users Print → Save as PDF — see the download route).
207	 *
208	 * `branding` is optional and defaults to the built-in values so this stays synchronous
209	 * and every existing caller keeps compiling. Async callers should pass
210	 * `await invoiceBranding()`; a caller that does not will render the platform defaults
211	 * (`INV-`, "Nxeon", no seller block) — identical to the pre-wiring output, never a blank.
212	 */
213	export function renderInvoiceHTML(
214	  invoice: Invoice,
215	  user: Pick<User, "name" | "email">,
216	  branding: InvoiceBranding = FALLBACK_BRANDING,
217	): string {
218	  const { items, subtotalCents, taxCents, totalCents } = invoiceTotals(invoice);
219	  const stamp = STATUS_STAMP[invoice.status] ?? STATUS_STAMP.OPEN;
220	  const number = formatInvoiceNumber(invoice.number, branding.numberPrefix);
221	  const period =
222	    invoice.periodStart || invoice.periodEnd
223	      ? `${fmtDate(invoice.periodStart)} – ${fmtDate(invoice.periodEnd)}`
224	      : null;
225	
226	  const rows = items
227	    .map(
228	      (li) => `
229	      <tr>
230	        <td class="desc">${esc(li.description)}</td>
231	        <td class="num">${esc(li.qty)}</td>
232	        <td class="num">${money(li.unitCents)}</td>
233	        <td class="num">${money(li.amountCents)}</td>
