107	/**
108	 * Dunning windows, all measured in DAYS PAST EXPIRY.
109	 *
110	 * Settings → Billing is the source of truth. Those three fields and the
111	 * "Auto-suspend overdue accounts" toggle used to be written to the Setting table and
112	 * read by NOTHING: the worker used env vars that were never set, so an operator who
113	 * turned suspensions off during an incident saw "Saved." and then watched the sweep
114	 * knock customer VMs offline ten minutes later.
115	 *
116	 * The legacy env vars remain as fallbacks, converted onto the days-past-expiry clock
117	 * so an operator who had set them keeps the behaviour they configured
118	 * (NXEON_TERMINATE_DAYS counted forward from the END of grace, and
119	 * NXEON_WARN_BEFORE_TERMINATE_DAYS counted backwards from termination).
120	 */
121	type DunningConfig = {
122	  /** Days past expiry before an account with no card in play is suspended. */
123	  graceDays: number;
124	  /** Days past expiry when the "will be deleted" warning goes out. */
125	  warnDays: number;
126	  /** Days past expiry when an unpaid SUSPENDED server is destroyed. */
127	  terminateDays: number;
128	  /** Admin kill switch: when false the sweep suspends and terminates nothing. */
129	  autoSuspend: boolean;
130	};
131	
132	const ENV_GRACE_DAYS = Number(process.env.NXEON_GRACE_DAYS ?? 3);
133	const ENV_TERMINATE_DAYS = process.env.NXEON_TERMINATE_DAYS
134	  ? ENV_GRACE_DAYS + Number(process.env.NXEON_TERMINATE_DAYS)
135	  : 14;
136	const ENV_WARN_DAYS = process.env.NXEON_WARN_BEFORE_TERMINATE_DAYS
137	  ? ENV_TERMINATE_DAYS - Number(process.env.NXEON_WARN_BEFORE_TERMINATE_DAYS)
138	  : 7;
139	
140	async function dunningConfig(): Promise<DunningConfig> {
141	  const graceDays = Math.max(0, await getSettingInt("dunning_grace_days", ENV_GRACE_DAYS));
142	  let terminateDays = await getSettingInt("dunning_terminate_days", ENV_TERMINATE_DAYS);
143	  let warnDays = await getSettingInt("dunning_warn_days", ENV_WARN_DAYS);
144	  const autoSuspend = await getSettingBool("auto_suspend_enabled", true);
145	
146	  // Clamp. These are free-text number fields in an admin panel and the action they
147	  // gate is irreversible — a typo (or a 0) must never be able to destroy a VM on the
148	  // same day it is suspended, or before the dunning sequence has even finished. The
149	  // floor includes the slip cap because a card sequence that started late can push
150	  // the suspension itself out to CARD_SUSPEND_DAY + SUSPEND_SLIP_CAP_DAYS, and
151	  // termination must always land AFTER the suspension it follows.
152	  const latestSuspendDay = Math.max(graceDays, CARD_SUSPEND_DAY + SUSPEND_SLIP_CAP_DAYS);
153	  terminateDays = Math.max(terminateDays, latestSuspendDay + 1);
154	  warnDays = Math.min(Math.max(warnDays, 1), terminateDays - 1);
155	  return { graceDays, warnDays, terminateDays, autoSuspend };
156	}
