158	const fmtUsd = (cents: number) => `$${(cents / 100).toFixed(2)}`;
159	/**
160	 * "Visa ···· 4242, expires 04/28" from the mirrored card columns on `User`.
161	 * The mirror is display-only — `stripePaymentMethodId` is what actually gets
162	 * charged — so this exists purely to keep the four column names in one place
163	 * instead of re-spelling them at every email and ledger description.
164	 */
165	const savedCardLabel = (u: {
166	  cardBrand: string | null;
167	  cardLast4: string | null;
168	  cardExpMonth: number | null;
169	  cardExpYear: number | null;
170	}) => cardDisplayLabel({ brand: u.cardBrand, last4: u.cardLast4, expMonth: u.cardExpMonth, expYear: u.cardExpYear });
171	const fmtDay = (d: Date) =>
172	  d.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric", timeZone: "UTC" });
173	const billingUrl = () => `${appUrl()}/dashboard/billing`;
