175	/**
176	 * Send a transactional email without ever letting the mailer stall billing.
177	 * `sendMail` already logs every attempt to EmailLog and returns false rather than
178	 * throwing; this is the belt-and-braces so an SMTP surprise can't abort a sweep
179	 * halfway through a money decision.
180	 */
181	async function mail(
182	  to: string,
183	  userId: string,
184	  tpl: { template?: string; subject: string; html: string },
185	  // Classifies the message for the preference policy in lib/prefs.ts. DEFAULTS TO
186	  // A CRITICAL KIND on purpose: nearly every mail from this sweep is a payment
187	  // failure, a 3-D Secure prompt, a final notice or a suspension warning, and none
188	  // of those may ever be suppressed by a preference. Only the receipt is
189	  // ACCOUNT-tier, so only the receipt passes "receipt" explicitly. Getting the
190	  // default the other way round would risk silencing a suspension warning.
191	  kind: NotifyKind = "payment_failed"
192	) {
193	  try {
194	    await sendMail({ to, subject: tpl.subject, html: tpl.html, template: tpl.template, userId, kind });
195	  } catch (e) {
196	    console.error("[billing] email send failed", e);
197	  }
198	}
