200	/** In-portal notice. Same never-throw contract as `mail` — bells are not money. */
201	async function notify(userId: string, title: string, body: string, href?: string) {
202	  try {
203	    await db.notification.create({ data: { userId, title, body, href } });
204	  } catch (e) {
205	    console.error("[billing] notification failed", e);
206	  }
