209	/** The renewal queue, and the row shape every card/dunning helper below works on. */
210	async function dueServers(now: Date) {
211	  return db.server.findMany({
212	    where: {
213	      isFree: false,
214	      expiresAt: { lt: now },
215	      status: { in: ["RUNNING", "STOPPED"] },
216	    },
217	    include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
218	  });
219	}
220	type DueServer = Awaited<ReturnType<typeof dueServers>>[number];
221	
222	/**
223	 * Subscription sweep, run periodically by the worker:
224	 *  - expired + autoRenew, wallet covers it     -> charge wallet, extend the term
225	 *  - expired + autoRenew, wallet falls short   -> apply the credit, auto-charge the
226	 *                                                 saved card for the remainder
227	 *  - card declined                             -> dunning (retry days 1/3/5 + email)
228	 *  - retries exhausted, or no card past grace  -> queue SUSPEND with unpaid note
229	 * Free servers (isFree) are never touched.
230	 */
231	export async function billingSweep() {
232	  const now = new Date();
233	  const cfg = await dunningConfig();
234	  const prices = {
235	    ipMonthlyCents: await dedicatedIpMonthlyCents(), // admin setting; 0 = included
236	    // Per-GB/month price for extra ROOT DISK. Read once per sweep; every server that
237	    // bought extra storage renews at plan + (extraDiskGB x this) x months, so the
238	    // upsell keeps billing every cycle rather than being a one-off charge.
239	    extraDiskPerGbCents: await extraDiskPerGbCents(),
240	  };
241	
242	  // Claim any card that was saved at Stripe but never confirmed in the browser,
243	  // BEFORE the renewal queries read card state — otherwise a customer who closed
244	  // the tab on Stripe's page gets dunned for a card we simply failed to record.
245	  try {
246	    const adopted = await adoptUnclaimedCards(now);
247	    if (adopted > 0) console.log(`[billing] adopted ${adopted} unconfirmed saved card(s)`);
248	  } catch (e) {
249	    console.error("[billing] card adoption error", e);
250	  }
251	
252	  // Renewal warnings: notify once when a paid server is within 3 days of expiry
253	  const soon = new Date(now.getTime() + 3 * 86400_000);
254	  const upcoming = await db.server.findMany({
255	    where: {
256	      isFree: false,
257	      expiresAt: { gt: now, lt: soon },
258	      status: { in: ["RUNNING", "STOPPED"] },
259	    },
260	    include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
261	  });
262	  for (const server of upcoming) {
263	    const warnCents = renewalCharge(server, prices).totalCents;
264	    // A customer with a card on file needs no warning and no top-up: the renewal
265	    // applies their wallet credit and auto-charges the card for the remainder.
266	    // Telling them to "top up to avoid suspension" would raise an alarm about a
267	    // suspension that is not going to happen.
268	    if (server.autoRenew && (server.user.balanceCents >= warnCents || hasChargeableCard(server.user))) {
269	      continue;
270	    }
271	    const already = await db.notification.findFirst({
272	      where: {
273	        userId: server.userId,
274	        title: { contains: server.hostname },
275	        createdAt: { gt: new Date(now.getTime() - 4 * 86400_000) },
276	        AND: { title: { contains: "renews soon" } },
277	      },
278	    });
279	    if (!already) {
280	      await db.notification.create({
281	        data: {
282	          userId: server.userId,
283	          title: `${server.hostname} renews soon — action needed`,
284	          body: server.autoRenew
285	            ? `Renewal is $${(warnCents / 100).toFixed(2)} but your balance is $${(server.user.balanceCents / 100).toFixed(2)}. Top up to avoid suspension.`
286	            : `Auto-renew is off. Renew manually before ${server.expiresAt!.toISOString().slice(0, 10)} to avoid suspension.`,
287	          href: `/dashboard/servers/${server.id}`,
288	        },
289	      });
290	    }
291	  }
292	  const due = await dueServers(now);
293	
294	  for (const server of due) {
295	    // One unhappy server must never abort the queue behind it. Every money write
296	    // below is individually guarded (CAS on expiresAt, UNIQUE on the payment intent
297	    // id, Stripe idempotency key), so continuing past a failure can only ever cost a
298	    // delayed renewal — never a duplicate charge. Without this, a single row with a
299	    // wedged Stripe customer would leave every later customer unrenewed AND
300	    // eventually suspended, for a fault that was entirely ours.
301	    try {
302	      await renewDueServer(server, { now, cfg, prices });
303	    } catch (e) {
304	      console.error(`[billing] renewal pass failed for ${server.hostname}`, e);
305	    }
306	  }
307	
308	  await terminateOverdue(now, cfg);
309	
310	  // Card housekeeping: nudge before a saved card expires, and honour the customer's
311	  // own automatic top-up preference. Both are isolated so a Stripe or SMTP problem
312	  // can never take the renewal sweep down with it.
313	  try {
314	    await cardExpirySweep(now);
315	  } catch (e) {
316	    console.error("[billing] card-expiry sweep error", e);
317	  }
318	  try {
319	    await autoRechargeSweep(now);
320	  } catch (e) {
321	    console.error("[billing] auto-recharge sweep error", e);
322	  }
323	
324	  await domainAutoRenewSweep(now);
325	
326	  // Poll in-flight inbound transfers on the same cadence as domain renewals —
327	  // domain upkeep all lives on one timer.
328	  try {
329	    await domainTransferInSweep(now);
330	  } catch (e) {
331	    console.error("[billing] domain transfer-in sweep error", e);
332	  }
333	}
