335	/**
336	 * One expired server: renew it from wallet + card, or move it along the dunning
337	 * sequence, or suspend it once every promised attempt is spent.
338	 */
339	async function renewDueServer(
340	  server: DueServer,
341	  ctx: { now: Date; cfg: DunningConfig; prices: { ipMonthlyCents: number; extraDiskPerGbCents: number } },
342	) {
343	  const { now, cfg, prices } = ctx;
344	  const charge = renewalCharge(server, prices);
345	  const renewCents = charge.totalCents;
346	  const base = new Date(Math.max(server.expiresAt!.getTime(), now.getTime()));
347	  const newExpiry = addMonths(base, charge.months);
348	
349	  await clearStaleDunning(server);
350	
351	  let renewed = false;
352	  if (server.autoRenew) {
353	    // `server.user.balanceCents` came from a snapshot taken before this loop and
354	    // is stale as soon as the first renewal in this pass debits a wallet, so the
355	    // SPLIT is computed from a fresh read. It is still never a gate: `debitWallet`
356	    // re-checks funds atomically and the compare-and-swap on `expiresAt` stops a
357	    // concurrent renewNow()/second pass charging the same period twice.
358	    const fresh = await db.user.findUnique({
359	      where: { id: server.userId },
360	      select: { balanceCents: true },
361	    });
362	    const split = walletSplit({
363	      dueCents: renewCents,
364	      balanceCents: fresh?.balanceCents ?? 0,
365	      useWallet: true,
366	    });
367	    const cardInPlay = hasChargeableCard(server.user);
368	
369	    if (split.cardCents === 0) {
370	      // Wallet covers the whole renewal — no card involved, no Stripe call.
371	      const outcome = await commitRenewal({ server, charge, newExpiry });
372	      renewed = outcome !== "insufficient";
373	      if (outcome === "renewed") {
374	        console.log(`[billing] renewed ${server.hostname} until ${newExpiry.toISOString()}`);
375	      }
376	    } else if (cardInPlay) {
377	      // Only attempt on the scheduled day. Without this gate a 10-minute sweep
378	      // would burn all three retries — and send all three emails — within half an
379	      // hour of the first decline.
380	      //
381	      // A scheduled time, once set, ALWAYS wins over the attempt counter, which buys
382	      // two things. `retryDunningNow` (fired when a customer saves a new card
383	      // mid-dunning) gets a real attempt even at the exhausted stage — refusing there
384	      // would suspend a customer whose brand-new card we never once tried. And the
385	      // exhausted stage's schedule points at the suspension day itself, so every
386	      // server gets one final, silent try at the card in the same pass that pauses it.
387	      const dueForRetry = server.dunningNextAt
388	        ? now >= server.dunningNextAt
389	        : server.dunningStage < DUNNING_EXHAUSTED;
390	      if (dueForRetry) {
391	        renewed = await attemptCardRenewal({
392	          server,
393	          charge,
394	          cardCents: split.cardCents,
395	          newExpiry,
396	          now,
397	          cfg,
398	        });
399	      }
400	    } else {
401	      console.log(
402	        `[billing] ${server.hostname} short by ${fmtUsd(split.cardCents)} and no card on file — grace/suspend applies`,
403	      );
404	    }
405	  }
406	
407	  if (renewed) {
408	    // nothing further this pass
409	  } else {
410	    const suspendAt = suspendDueAt(server, hasChargeableCard(server.user), cfg);
411	    if (suspendAt && now >= suspendAt) {
412	      await suspendUnpaid(server, cfg);
413	    }
414	  }
415	}
