417	/**
418	 * Drop dunning state that belongs to a period we are no longer collecting for.
419	 *
420	 * `renewNow` (lib/actions.ts) advances `expiresAt` without touching the dunning
421	 * columns, so a customer who paid by hand halfway through a sequence carries a
422	 * stale `dunningStage` into the NEXT period — and the first decline of that fresh
423	 * period would arrive as "payment retry 2 declined, 1 attempt remaining", on a
424	 * compressed schedule, for a period they had never failed once.
425	 *
426	 * Every schedule this file writes lands at or after the expiry it was computed
427	 * from, so a `dunningNextAt` that predates the CURRENT `expiresAt` can only have
428	 * been written for an older, already-settled period.
429	 */
430	async function clearStaleDunning(server: DueServer): Promise<void> {
431	  if (server.dunningStage === 0 && !server.dunningNextAt && !server.dunningPayUrl) return;
432	  const belongsToThisPeriod = server.dunningNextAt && server.dunningNextAt >= server.expiresAt!;
433	  if (belongsToThisPeriod) return;
434	
435	  await db.server.update({
436	    where: { id: server.id },
437	    data: { dunningStage: 0, dunningNextAt: null, dunningPayUrl: null },
438	  });
439	  // Keep the in-memory row honest: the rest of this pass reads these fields to
440	  // decide whether to charge, which email to send and when to suspend.
441	  server.dunningStage = 0;
442	  server.dunningNextAt = null;
443	  server.dunningPayUrl = null;
444	}
445	
446	/* ------------------------------------------------------------------ *
447	 * Renewal commit (wallet) + card auto-charge
448	 * ------------------------------------------------------------------ */
449	
450	/**
451	 * Advance the term and take the money from the wallet, atomically.
452	 *
453	 * This is the ONLY place a VPS renewal is granted, whether the wallet was funded
454	 * by a top-up, a referral credit or the saved card moments ago. One money path
455	 * means a partial failure can never half-apply a renewal: either the period
456	 * advances AND the wallet is debited AND the invoice exists, or none of it happened.
457	 *
458	 * The compare-and-swap on `expiresAt` is the idempotency guard. A retried sweep, a
459	 * second worker or a concurrent `renewNow` all read the same snapshot expiry; only
460	 * the first `updateMany` to match it writes, and every loser rolls back its debit
461	 * and its invoice with the transaction. Zero rows matched = someone else already
462	 * renewed this period, which is a success for us, not an error.
463	 */
464	async function commitRenewal(opts: {
465	  server: DueServer;
466	  charge: RenewalCharge;
467	  newExpiry: Date;
468	}): Promise<"renewed" | "insufficient" | "already"> {
469	  const { server, charge, newExpiry } = opts;
470	  const renewCents = charge.totalCents;
471	  const { extraDiskCents, extraDiskMonthlyCents } = charge;
472	  const periodStart = server.expiresAt!;
473	
474	  try {
475	    await db.$transaction(async (tx) => {
476	      const advanced = await tx.server.updateMany({
477	        where: { id: server.id, expiresAt: server.expiresAt },
478	        data: {
479	          expiresAt: newExpiry,
480	          // The period is paid, so the collection state that belonged to it dies
481	          // with it. Leaving a stage behind would hand the NEXT period a
482	          // half-spent retry budget and the wrong dunning email.
483	          dunningStage: 0,
484	          dunningNextAt: null,
485	          dunningPayUrl: null,
486	        },
487	      });
488	      if (advanced.count === 0) throw new AlreadyRenewedError();
489	      await debitWallet(tx, server.userId, renewCents);
490	      await tx.walletTransaction.create({
491	        data: {
492	          userId: server.userId,
493	          amountCents: -renewCents,
494	          description: `Renewal: ${charge.label} (${server.hostname})`,
495	        },
496	      });
497	      // PAID invoice for this renewal period. Inside the CAS-guarded tx, so a
498	      // retried/concurrent sweep hits AlreadyRenewedError and rolls back —
499	      // never producing a second invoice for the same period.
500	      await tx.invoice.create({
501	        data: invoiceCreateData({
502	          userId: server.userId,
503	          description: `Renewal: ${charge.label} (${server.hostname})`,
504	          status: "PAID",
505	          period: { start: periodStart, end: newExpiry },
506	          // Extra disk gets its OWN line so the customer sees exactly what the
507	          // permanent storage costs each cycle; the lines sum back to renewCents.
508	          lineItems: [
509	            {
510	              description: `${charge.label} — ${server.hostname}`,
511	              qty: 1,
512	              unitCents: renewCents - extraDiskCents,
513	              amountCents: renewCents - extraDiskCents,
514	            },
515	            ...(extraDiskCents > 0
516	              ? [
517	                  {
518	                    description: `${extraDiskLabel(server.extraDiskGB)} — ${server.hostname} (permanent, $${(extraDiskMonthlyCents / 100).toFixed(2)}/mo)`,
519	                    qty: 1,
520	                    unitCents: extraDiskCents,
521	                    amountCents: extraDiskCents,
522	                  },
523	                ]
524	              : []),
525	          ],
526	        }),
527	      });
528	      await tx.auditLog.create({
529	        data: { userId: server.userId, action: "billing.renewed", detail: server.id },
530	      });
531	    });
532	  } catch (e) {
533	    if (e instanceof InsufficientBalanceError) {
534	      console.log(`[billing] insufficient balance for ${server.hostname} — falling through to grace/suspend`);
535	      return "insufficient";
536	    }
537	    if (e instanceof AlreadyRenewedError) return "already"; // someone else advanced the period
538	    throw e;
539	  }
540	
541	  // The period is settled. Any 3-D Secure challenge still hanging off it is a
542	  // loaded gun: anything that later confirms that intent takes a SECOND payment
543	  // for a period we have already been paid for. Only worth a Stripe round-trip
544	  // when this server was actually mid-dunning.
545	  if (server.dunningStage > 0 || server.dunningPayUrl) {
546	    await cancelPendingChargeForMarker(
547	      server.user.stripeCustomerId,
548	      renewalChargeMarker(server.id, periodStart),
549	    );
550	  }
551	  return "renewed";
552	}
553	
554	/**
555	 * Charge the saved card for the wallet shortfall, then renew.
556	 *
557	 * The card NEVER pays the invoice directly. It credits the wallet with exactly
558	 * what Stripe captured, and `commitRenewal` then debits the FULL renewal from the
559	 * wallet — identical to how checkout splits a purchase. That ordering is what
560	 * makes a crash safe in both directions: money captured but not yet applied sits
561	 * in the customer's wallet as credit (visible, spendable, refundable), and a
562	 * renewal can never be granted without a matching debit.
563	 *
564	 * TWO idempotency guards ride on every attempt:
565	 *  - `marker` (server + period) — a permanent pre-flight lookup at Stripe for a
566	 *    live PaymentIntent for this exact period, so a crash between "Stripe captured"
567	 *    and "we recorded it" replays instead of charging again.
568	 *  - `idempotencyKey` (server + period + attempt + amount) — Stripe replays an
569	 *    identical request for 24h, which covers two overlapping sweeps of the SAME
570	 *    scheduled attempt. The attempt and amount are in the key because a genuine
571	 *    day-3 retry, or a retry for a different remainder after the wallet moved, is a
572	 *    deliberately NEW charge; reusing the key there would make Stripe reject it.
573	 *
574	 * And the credit itself is guarded by the UNIQUE index on
575	 * `WalletTransaction.stripePaymentIntentId`, so even a replayed capture credits once.
576	 *
577	 * @returns true when the term was actually extended.
578	 */
579	async function attemptCardRenewal(opts: {
580	  server: DueServer;
581	  charge: RenewalCharge;
582	  cardCents: number;
583	  newExpiry: Date;
584	  now: Date;
585	  cfg: DunningConfig;
586	}): Promise<boolean> {
587	  const { server, charge, cardCents, newExpiry, now, cfg } = opts;
588	  const user = server.user;
589	  const periodStart = server.expiresAt!;
590	  const marker = renewalChargeMarker(server.id, periodStart);
591	  const idempotencyKey = `nxeon_renew_${server.id}_${periodStart.getTime()}_a${server.dunningStage}_${cardCents}`;
592	  const cardLabel = savedCardLabel(user) ?? "your saved card";
593	
594	  const result = await chargeSavedCardOffSession({
595	    user,
596	    amountCents: cardCents,
597	    description: `Renewal: ${charge.label} (${server.hostname})`,
598	    marker,
599	    idempotencyKey,
600	    metadata: {
601	      nxeonServerId: server.id,
602	      nxeonPeriodStart: periodStart.toISOString(),
603	      nxeonKind: "renewal",
604	    },
605	  });
606	
607	  if (result.ok) {
608	    // Exactly what Stripe took, not what we asked for — a replayed intent can carry
609	    // an older amount and the ledger must match the bank, not our intent.
610	    const credited = await creditOffSessionCharge({
611	      userId: server.userId,
612	      amountCents: result.amountCents,
613	      description: `Card payment for ${server.hostname} renewal (${cardLabel})`,
614	      paymentIntentId: result.paymentIntentId,
615	      // No invoice for the card leg: `commitRenewal` issues ONE paid invoice for
616	      // the whole renewal, and a second document for the card portion would
617	      // double-count the same revenue.
618	    });
619	    const outcome = await commitRenewal({ server, charge, newExpiry });
620	
621	    // The receipt is tied to the CREDIT, not the renewal: `creditOffSessionCharge`
622	    // returns false on the P2002 that means "already credited", so a replayed
623	    // capture cannot email the same customer a second receipt for one charge.
624	    if (credited) {
625	      await mail(
626	        user.email,
627	        user.id,
628	        emails.paymentReceipt(
629	          fmtUsd(result.amountCents),
630	          `${charge.label} — ${server.hostname}`,
631	          user.cardLast4 ?? "",
632	        ),
