749	  server: DueServer;
750	  cardCents: number;
751	  now: Date;
752	  cfg: DunningConfig;
753	  reason: string;
754	}): Promise<void> {
755	  const { server, cardCents, now, cfg, reason } = opts;
756	  const prevStage = server.dunningStage;
757	  const newStage = Math.min(prevStage + 1, DUNNING_EXHAUSTED);
758	  const amount = fmtUsd(cardCents);
759	  const last4 = server.user.cardLast4 ?? "";
