804	  await db.server.update({
805	    where: { id: server.id },
806	    data: { dunningStage: newStage, dunningNextAt: scheduledAt },
807	  });
808	  server.dunningStage = newStage;
809	  server.dunningNextAt = scheduledAt;
810	
811	  await db.auditLog
812	    .create({
813	      data: {
814	        userId: server.userId,
815	        action: "billing.card_declined",
816	        detail: `${server.id}: attempt ${newStage} for ${amount} — ${reason.slice(0, 180)}`,
817	      },
818	    })
