890	/**
891	 * When this overdue server may be paused — null means never (auto-suspend is off).
892	 *
893	 * With a card in play the deadline is CARD_SUSPEND_DAY past expiry: one clear day
894	 * after the final-notice email, so the customer always gets a full day with the
895	 * warning in hand before anything stops. Without a card there is nothing to wait
896	 * for beyond the configured grace period.
897	 *
898	 * The deadline also never lands BEFORE a date we have promised the customer. A
899	 * worker that was down for the first five days starts the sequence late, and
900	 * suspending on the calendar alone would then pause a server minutes after emailing
901	 * "we'll try your card again on <date>" or "this is your final notice" — the exact
902	 * broken promise this whole feature exists to stop. `dunningNextAt` carries that
903	 * promise (the next attempt while any remain, the clear day once they are spent),
904	 * and the slip it can buy is capped by SUSPEND_SLIP_CAP_DAYS so a permanently
905	 * failing Stripe cannot defer suspension forever.
906	 */
907	function suspendDueAt(
908	  server: { expiresAt: Date | null; dunningStage: number; dunningNextAt: Date | null },
909	  hasCard: boolean,
910	  cfg: DunningConfig,
911	): Date | null {
912	  if (!cfg.autoSuspend || !server.expiresAt) return null;
913	  const days = calendarSuspendDay(cfg, hasCard);
914	  const at = new Date(server.expiresAt.getTime() + days * DAY);
915	  if (!hasCard || !server.dunningNextAt || server.dunningNextAt <= at) return at;
916	  const cap = new Date(server.expiresAt.getTime() + (days + SUSPEND_SLIP_CAP_DAYS) * DAY);
917	  return server.dunningNextAt < cap ? server.dunningNextAt : cap;
918	}
