941	  // duplicate jobs against one VM are how a suspend/unsuspend race leaves a paid-up
942	  // customer offline.
943	  const pending = await db.job.count({
944	    where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
945	  });
946	  if (pending !== 0) return;
947	
948	  await db.server.update({
949	    where: { id: server.id },
950	    data: {
951	      suspendedNote: "unpaid — renew from your billing page to restore access",
952	      // Only an UNPAID suspension may be terminated by the overdue sweep or
953	      // lifted automatically by paying. See Server.suspendReason.
954	      suspendReason: "UNPAID",
955	    },
956	  });
957	  await db.job.create({ data: { type: "SUSPEND", serverId: server.id } });
