992	  const renudgeBefore = new Date(now.getTime() - CARD_EXPIRY_RENUDGE_DAYS * DAY);
993	
994	  const users = await db.user.findMany({
995	    where: {
996	      suspended: false,
997	      stripePaymentMethodId: { not: null },
998	      cardExpMonth: { not: null },
999	      cardExpYear: { not: null },
1000	      OR: [{ cardExpiryNotifiedAt: null }, { cardExpiryNotifiedAt: { lt: renudgeBefore } }],
1001	    },
