1149	/* ------------------------------------------------------------------ *
1150	 * Inbound domain transfers (transfer-in)
1151	 * ------------------------------------------------------------------ */
1152	
1153	/** Remind the customer to approve the confirmation email at most this often. */
1154	const TRANSFER_NUDGE_DAYS = 3;
1155	
1156	/**
1157	 * Poll every TRANSFER_PENDING domain and move it to its real state.
1158	 *
1159	 * An ICANN transfer takes ~5-7 days and only completes once the owner approves
1160	 * an email from the LOSING registrar, so this is a slow poll, not a spinner:
1161	 *   completed -> ACTIVE, dates taken from the registrar, auth code scrubbed
1162	 *   failed    -> TRANSFER_FAILED, wallet credited back, reason recorded
1163	 *   pending   -> raw registrar status refreshed for display, gentle nudge
1164	 *
1165	 * Every mutation goes through the shared CAS-guarded settle helpers, so a
1166	 * re-run, two workers racing, or a customer cancelling at the same moment can
1167	 * never credit the same transfer twice.
1168	 */
1169	async function domainTransferInSweep(now: Date) {
1170	  if (!transfersAvailable()) return; // registrar not configured — skip silently
1171	
1172	  const pending = await db.domain.findMany({
1173	    where: { status: "TRANSFER_PENDING", isTransferIn: true },
1174	  });
1175	
1176	  for (const domain of pending) {
1177	    try {
1178	      const info = await getTransfer(domain.name, domain.transferStartedAt);
1179	
1180	      // No transfer on record. Normal once a transfer settles and drops off the
1181	      // registrar's list — resolve it against the account rather than guessing.
1182	      if (!info) {
1183	        const owned = await domainInfo(domain.name).catch(() => null);
1184	        if (owned?.expires) {
1185	          await completeTransferIn(domain, "completed", owned);
1186	          continue;
1187	        }
1188	        const startedAt = domain.transferStartedAt ?? domain.createdAt;
1189	        const ageDays = (now.getTime() - startedAt.getTime()) / DAY;
1190	        if (ageDays > TRANSFER_STALE_DAYS) {
1191	          await failTransferIn(
1192	            domain,
1193	            null,
1194	            `The registrar has no record of this transfer after ${Math.round(ageDays)} days. It did not complete.`
1195	          );
1196	        }
1197	        continue;
1198	      }
1199	
1200	      const outcome = transferOutcome(info.status);
1201	
1202	      if (outcome === "completed") {
1203	        const owned = await domainInfo(domain.name).catch(() => null);
1204	        await completeTransferIn(domain, info.status, owned);
1205	        continue;
1206	      }
1207	
1208	      if (outcome === "failed") {
1209	        await failTransferIn(domain, info.status, transferStatusLabel(info.status));
1210	        continue;
1211	      }
1212	
1213	      // Still in flight — keep the displayed registrar status fresh.
1214	      if (info.status !== domain.transferStatus || (info.email && info.email !== domain.transferEmail)) {
1215	        await db.domain.update({
1216	          where: { id: domain.id },
1217	          data: { transferStatus: info.status, ...(info.email ? { transferEmail: info.email } : {}) },
1218	        });
1219	      }
1220	      await nudgeTransferApproval(domain, info.status, info.email, now);
1221	    } catch (e) {
1222	      // One unhappy domain must never abort the sweep. Nothing is settled and
1223	      // no money moves on an unknown state — we simply try again next pass.
1224	      console.error(`[billing] transfer-in poll failed for ${domain.name}`, e);
1225	    }
1226	  }
1227	}
