35	// ---------- Admin: create ----------
36	
37	const createSchema = z.object({
38	  amount: z.coerce.number().positive().max(10000),
39	  note: z.string().max(200).optional(),
40	  count: z.coerce.number().int().min(1).max(100),
41	});
42	
43	/**
44	 * Create one or more gift/credit codes. `amount` is dollars (converted to
45	 * cents), `count` bulk-generates N codes with the same amount/note.
46	 */
47	export async function adminCreateGiftCodes(
48	  prev: any,
49	  formData: FormData
50	): Promise<{ error?: string; ok?: boolean; codes?: string[] }> {
51	  const admin = await requireArea("billing");
52	  const rawNote = String(formData.get("note") ?? "").trim();
53	  const parsed = createSchema.safeParse({
54	    amount: formData.get("amount"),
55	    note: rawNote === "" ? undefined : rawNote,
56	    count: formData.get("count") || 1,
57	  });
58	  if (!parsed.success) {
59	    return { error: parsed.error.issues[0]?.message ?? "Invalid gift code details." };
60	  }
61	  const { amount, note, count } = parsed.data;
62	  const amountCents = Math.round(amount * 100);
63	  if (amountCents < 1) return { error: "Amount must be at least $0.01." };
64	
65	  const codes: string[] = [];
66	  for (let i = 0; i < count; i++) {
67	    const code = await uniqueGiftCode();
68	    await db.giftCode.create({
69	      data: { code, amountCents, note: note ?? null },
70	    });
71	    codes.push(code);
72	  }
73	
74	  await db.auditLog.create({
75	    data: {
76	      userId: admin.id,
77	      action: "admin.giftcode_create",
78	      detail: `${count} x $${amount.toFixed(2)}`,
79	    },
80	  });
81	  revalidatePath("/admin/gift-codes");
82	  return { ok: true, codes };
83	}
84	
85	// ---------- Admin: delete (unredeemed only) ----------
86	
87	export async function adminDeleteGiftCode(id: string): Promise<void> {
88	  const admin = await requireArea("billing");
89	  const gift = await db.giftCode.findUnique({ where: { id } });
90	  if (!gift) return;
91	  if (gift.redeemedById) return; // never delete a redeemed code
92	  await db.giftCode.delete({ where: { id } });
93	  await db.auditLog.create({
94	    data: { userId: admin.id, action: "admin.giftcode_delete", detail: gift.code },
95	  });
96	  revalidatePath("/admin/gift-codes");
97	}
98	
99	// ---------- Customer: redeem ----------
100	
101	/**
102	 * Redeem a gift code into the current user's wallet. Race-safe: the claim is an
103	 * `updateMany` guarded by `redeemedById: null` inside a transaction, so two
104	 * concurrent redemptions of the same code can only ever succeed once.
105	 */
106	export async function redeemGiftCode(
107	  rawCode: string
108	): Promise<{ ok?: boolean; error?: string; amountCents?: number }> {
109	  const user = await requireUser();
110	  const code = String(rawCode ?? "").trim().toUpperCase();
111	  if (!code) return { error: "Enter a gift code." };
112	
113	  const gift = await db.giftCode.findUnique({ where: { code } });
114	  if (!gift) return { error: "That code isn't valid. Check for typos and try again." };
115	  if (gift.redeemedById) return { error: "This code has already been redeemed." };
116	
117	  const result = await db.$transaction(async (tx) => {
118	    // Atomic claim: only succeeds if the code is still unredeemed.
119	    const claim = await tx.giftCode.updateMany({
120	      where: { id: gift.id, redeemedById: null },
121	      data: { redeemedById: user.id, redeemedAt: new Date() },
122	    });
123	    if (claim.count !== 1) return { error: "This code has already been redeemed." };
124	
125	    await tx.user.update({
126	      where: { id: user.id },
127	      data: { balanceCents: { increment: gift.amountCents } },
128	    });
129	    await tx.walletTransaction.create({
130	      data: {
131	        userId: user.id,
132	        amountCents: gift.amountCents,
133	        description: `Gift code redeemed (${gift.code})`,
134	      },
135	    });
136	    return { ok: true, amountCents: gift.amountCents };
137	  });
138	
139	  if (result.ok) {
140	    revalidatePath("/dashboard/billing");
141	  }
142	  return result;
143	}
