70	          Code <span className="font-mono">{applied.code}</span> applied — {applied.label}
71	        </span>
72	        {/* Validated against a nominal $25 (PREVIEW_CENTS) because no amount has
73	            been chosen yet — `topUp` re-checks the code against the real amount,
74	            so a code with a minimum spend can still fall away. Say so rather than
75	            let the customer read this as unconditional. */}
76	        <span className="text-xs text-slate-400">
77	          Bonus is credited when you add funds. Codes with a minimum spend are re-checked against
78	          the amount you enter.
79	        </span>
80	        <button type="button" onClick={remove} className="btn-ghost ml-auto py-1 text-xs">
81	          Remove
82	        </button>
83	      </div>
84	    );
85	  }
86	
87	  return (
88	    <div>
89	      <label className="label">Promo code</label>
90	      <div className="flex items-center gap-2">
91	        <input
92	          className="input w-48 uppercase"
93	          value={code}
94	          onChange={(e) => setCode(e.target.value)}
95	          placeholder="WELCOME10"
96	          maxLength={32}
97	          onKeyDown={(e) => {
