104	        <button type="button" className="btn-secondary py-2" onClick={apply} disabled={pending}>
105	          {pending ? "Checking…" : "Apply"}
106	        </button>
107	      </div>
108	      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
109	    </div>
110	  );
111	}
