// ---------- Wallet (demo top-up until a payment gateway is connected) ----------

export async function topUp(prev: any, formData: FormData): Promise<{ error?: string }> {
  const user = await requireUser();
  // Spend/credit path: block while impersonating so an admin can't mint or move
  // a customer's balance on their behalf.
  await assertNotImpersonating();
  // Security: never mint free wallet balance in production. The demo gateway that
  // credits without a real payment is only ever acceptable in non-production, and
  // is refused outright when NODE_ENV === "production" regardless of Stripe.
  if (process.env.NODE_ENV === "production") {
    return { error: "Please add funds with a card via the secure checkout." };
  }
  // Once Stripe is configured, the demo gateway is hard-disabled — top-ups must
  // go through Checkout.
  const { stripeConfigured } = await import("./stripe");
  if (stripeConfigured()) {
    return { error: "Please add funds with a card via the secure checkout." };
  }
  // Throttle demo top-ups per user+IP to prevent rapid free-credit minting.
  const topupHdrs = await headers();
  const topupIp = (topupHdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
  const topupRl = checkRateLimit(`topup:${user.id}:${topupIp}`, { max: 10, windowMs: 60 * 60 * 1000 });
  if (!topupRl.ok) {
    return { error: `Too many top-up attempts. Try again in ${topupRl.retryAfterSec}s.` };
  }
  const amount = Number(formData.get("amount"));
  if (!Number.isFinite(amount) || amount < 1 || amount > 1000) {
    return { error: "Amount must be between $1 and $1000." };
  }
  const cents = Math.round(amount * 100);
  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
  const minTopup = await getSettingInt("min_topup_cents", 500);
  if (cents < minTopup) {
    return { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}.` };
  }

  // Optional promo code: applied via the COUPON_COOKIE the billing CouponField
  // sets. applyCouponToTopup re-validates for this user against the real amount.
  const jar = await cookies();
  const couponCode = jar.get(COUPON_COOKIE)?.value?.trim();
  let bonusCents = 0;
  let couponId: string | null = null;
  let couponLabel = "";
  if (couponCode) {
    const result = await applyCouponToTopup(couponCode, cents);
    if (result.ok) {
      bonusCents = result.bonusCents;
      couponId = result.couponId;
      couponLabel = result.label;
    } else {
      // REFUSE, don't silently drop. The old code fell through and completed the
      // top-up with no bonus and no message, so a code that passed validation at
      // the preview amount but fails against the real one (a `minAmountCents`
      // floor, an exhausted limit, an expiry) simply vanished — the customer paid
      // expecting a bonus and got nothing, with nowhere to look. Nothing has been
      // charged at this point, so stopping is free and the customer can retry
      // without the code or with a larger amount.
      return {
        error:
          `${result.error ?? "That promo code can't be applied to this amount."} ` +
          `Nothing has been charged — adjust the amount or remove the code and try again.`,
      };
    }
  }

  await db.$transaction([
    db.user.update({
      where: { id: user.id },
      data: { balanceCents: { increment: cents + bonusCents } },
    }),
    db.walletTransaction.create({
      data: { userId: user.id, amountCents: cents, description: "Wallet top-up (demo gateway)" },
    }),
    ...(bonusCents > 0 && couponId
      ? [
          db.walletTransaction.create({
            data: {
              userId: user.id,
              amountCents: bonusCents,
              description: `Promo ${couponCode!.toUpperCase()} — ${couponLabel}`,
            },
          }),
          db.couponRedemption.create({
            data: { couponId, userId: user.id, amountCents: bonusCents, context: "topup" },
          }),
          db.coupon.update({
            where: { id: couponId },
            data: { timesRedeemed: { increment: 1 } },
          }),
        ]
      : []),
  ]);
  jar.delete(COUPON_COOKIE);
  await audit(user.id, "wallet.topup", `$${amount}${bonusCents > 0 ? ` +bonus $${(bonusCents / 100).toFixed(2)}` : ""}`);
  // First successful paid action may unlock a referral reward for both parties.
  try {
    await maybeRewardReferral(user.id);
  } catch { /* non-fatal */ }
  revalidatePath("/dashboard/billing");
  return {};
}

