2	 * Shared per-server DISK EXPANSION core — the money path for growing a single
3	 * server's OWN root disk without touching its plan's CPU/RAM/price.
4	 *
5	 * Used by the wallet flow (lib/actions-disk.ts expandServerDisk) and by the
6	 * Stripe confirm route so a paid checkout can apply the expansion immediately.
7	 * Plain server module (NOT "use server") — same shape as lib/resize.ts, and it
8	 * deliberately mirrors that file line-for-line so the two money paths can never
9	 * drift apart.
10	 *
11	 * ─── GROWTH IS ONE-WAY ──────────────────────────────────────────────────────
12	 * There is no shrink counterpart to `applyDiskExpand`, and nothing here (or
13	 * anywhere else) ever decrements `Server.extraDiskGB`.
14	 *
15	 * ─── WHY THIS CANNOT DOUBLE-CHARGE ──────────────────────────────────────────
16	 *  1. `diskExpandQuote` is the ONLY place the prorated amount is computed, and
17	 *     both the wallet path and the Stripe-confirm path call it.
18	 *  2. The wallet is debited exactly once, inside the same $transaction that
19	 *     creates the DISK_EXPAND job — a rolled-back debit leaves no job, and a
20	 *     job that exists was always paid for.
21	 *  3. On the card path the wallet is NOT touched until Stripe clears: checkout
22	 *     charges only the card remainder, the confirm route credits that remainder
23	 *     to the wallet and then debits the FULL proration, so the two net out.
24	 *  4. `creditCheckoutSession`'s UNIQUE(stripeSessionId) makes the confirm route
25	 *     idempotent — a reloaded/replayed confirm URL credits (and therefore
26	 *     applies) nothing a second time.
27	 *  5. `Server.extraDiskGB` is advanced by the WORKER on success, never here, so
28	 *     a failed expansion is refunded by the worker's reconcile pass and the
29	 *     customer never renews on storage they didn't get.
30	 */
31	import { db } from "./db";
32	import { debitWallet, InsufficientBalanceError } from "./wallet";
33	import { invoiceCreateData } from "./invoices";
34	import { getSettingInt } from "./settings";
35	import { diskCapacityCheck } from "./capacity";
36	import { MS_PER_AVG_MONTH } from "./resize";
37	import {
38	  EXTRA_DISK_DEFAULT_PER_GB_CENTS,
39	  EXTRA_DISK_MAX_TOTAL_GB,
40	  EXTRA_DISK_MIN_GB,
41	  EXTRA_DISK_STEP_GB,
42	  effectiveDiskGB,
43	  extraDiskCentsAt,
44	  extraDiskLabel,
45	  isValidExtraDiskAddGB,
46	} from "./extra-disk";
47	
48	export class DiskExpandError extends Error {}
49	
50	/**
51	 * The per-GB/month price actually charged, from the admin setting
52	 * (`extra_disk_gb_price_cents`, default 10 = $0.10/GB/mo). Single source of
53	 * truth for every order/expansion/renewal/display path so they can't disagree.
54	 */
55	export async function extraDiskPerGbCents(): Promise<number> {
56	  const v = await getSettingInt("extra_disk_gb_price_cents", EXTRA_DISK_DEFAULT_PER_GB_CENTS);
57	  return Math.max(0, Math.round(v));
58	}
59	
60	/** Monthly charge (integer cents) for `gb` GB of extra disk at the current price. */
61	export async function extraDiskMonthlyCents(gb: number): Promise<number> {
62	  if (!gb || gb <= 0) return 0;
63	  return extraDiskCentsAt(gb, await extraDiskPerGbCents());
64	}
65	
66	type QuotedServer = NonNullable<Awaited<ReturnType<typeof loadServer>>>;
67	
68	function loadServer(serverId: string) {
69	  return db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
70	}
71	
72	export type DiskExpandQuote = {
73	  server: QuotedServer;
74	  /** GB being added in THIS purchase. */
75	  addGB: number;
76	  /** `extraDiskGB` the server will hold once the worker finishes. */
77	  targetExtraDiskGB: number;
78	  /** Effective disk (plan + extra) after the expansion. */
79	  newTotalDiskGB: number;
80	  perGbCents: number;
81	  /** Recurring monthly cost of the newly-added GB (billed every renewal). */
82	  monthlyCents: number;
83	  /** One-off charge for the remainder of the CURRENT paid term. */
84	  prorateCents: number;
85	};
86	
87	/**
88	 * Validate an expansion and compute the prorated charge over the ACTUAL
89	 * remaining duration — identical maths to `resizeQuote` (monthly cost × every
90	 * remaining month; null expiresAt on free/admin servers => 0). Throws
91	 * DiskExpandError with a user-facing message on any guard failure. Does NOT
92	 * check ownership — callers must do that.
93	 */
94	export async function diskExpandQuote(serverId: string, addGB: number): Promise<DiskExpandQuote> {
95	  const server = await loadServer(serverId);
96	  if (!server) throw new DiskExpandError("Not found");
97	  if (!isValidExtraDiskAddGB(addGB)) {
98	    throw new DiskExpandError(
99	      `Choose between ${EXTRA_DISK_MIN_GB} and 500 GB, in ${EXTRA_DISK_STEP_GB} GB steps.`,
100	    );
101	  }
102	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
103	    throw new DiskExpandError("Server is busy — wait for the current operation to finish.");
104	  }
105	  if (!server.vmid) throw new DiskExpandError("This server hasn't finished provisioning yet.");
106	
107	  const targetExtraDiskGB = server.extraDiskGB + addGB;
108	  const newTotalDiskGB = effectiveDiskGB(server.plan.diskGB, targetExtraDiskGB);
109	  if (newTotalDiskGB > EXTRA_DISK_MAX_TOTAL_GB) {
110	    throw new DiskExpandError(
111	      `A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB — this would take it to ${newTotalDiskGB} GB. Contact support for larger volumes.`,
112	    );
113	  }
114	
115	  // Don't sell space the node can't physically back.
116	  const cap = await diskCapacityCheck(server.nodeId, addGB);
117	  if (!cap.ok) throw new DiskExpandError(cap.reason ?? "Not enough storage available right now.");
118	
119	  const perGbCents = await extraDiskPerGbCents();
120	  const monthlyCents = extraDiskCentsAt(addGB, perGbCents);
121	
122	  let prorateCents = 0;
123	  if (!server.isFree && server.expiresAt) {
124	    const remainingMonths = Math.max(0, (server.expiresAt.getTime() - Date.now()) / MS_PER_AVG_MONTH);
125	    prorateCents = Math.max(0, Math.round(monthlyCents * remainingMonths));
126	  }
127	  return { server, addGB, targetExtraDiskGB, newTotalDiskGB, perGbCents, monthlyCents, prorateCents };
128	}
