import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import {
  MS_PER_AVG_MONTH,
  prorateDeltaCents,
  prorateUpgradeCents,
  prorateDowngradeCreditCents,
  remainingMonths,
} from "../lib/proration.ts";
import { vpsTermPriceCents } from "../lib/billing-terms.ts";
import { currentPromo, promoPriceCents, LAUNCH_SALE, type Promo } from "../lib/promotions.ts";

/**
 * REAL INCIDENTS — docs/QA-PRELAUNCH.md P0-6 (and its mirror image):
 *
 *  1. Upgrade proration priced the RAW list-price monthly delta while the original
 *     order applied both the term discount and the seasonal promo. On a 36-month
 *     term with the 30% Summer Sale running, upgrading Starter -> Max the day after
 *     purchase cost $1,044.45 against $665.08 for buying Max outright on the same
 *     end date: the customer overpaid $379.37.
 *  2. The downgrade CREDIT used that same undiscounted delta, so it refunded more
 *     than had ever been paid — a self-service money printer that was one
 *     cheap-but-storage-heavy plan away from reachable (blocked today only by the
 *     disk-monotonic guard, QA P1-14).
 *  3. The fix for (2) also CAPPED the credit's duration at one term while the
 *     charge side kept pricing every remaining month, which broke the round trip in
 *     the other direction. A customer whose stacked "Renew now" had pushed
 *     `expiresAt` 36 months out on a 12-month term paid $544.32 to go
 *     Starter -> Max and got $181.44 back coming straight down: the platform kept
 *     $362.88 of months they had paid for. `remainingMonths` no longer takes a cap
 *     at all, so the two directions cannot express different durations.
 *
 * Both directions now price through lib/proration.ts. These tests hold the two
 * halves against each other so they cannot drift apart again.
 *
 * Deterministic: every `now` and every promo is injected — nothing reads the clock
 * except through a value supplied by the test.
 */

/** Live plan catalogue (cents/month) at the time of the incident. */
const STARTER = 899;
const MAX = 3299;
const TERM = 36;

/** The 30% Summer Sale — the promo running when P0-6 was measured. */
const PROMO = currentPromo(new Date("2026-07-26T12:00:00.000Z"));
const NO_PROMO: Promo = { ...LAUNCH_SALE, discountPercent: 0 };

/** What a FRESH order for `monthly` over `TERM` costs today (lib/order.ts). */
const freshOrderCents = (monthly: number, promo: Promo) =>
  promoPriceCents(vpsTermPriceCents(monthly, TERM), promo);

test("the promo and catalogue this file is pinned to have not moved", () => {
  assert.equal(PROMO.discountPercent, 30);
  assert.equal(freshOrderCents(STARTER, PROMO), 18124, "Starter, 36mo, -20% term, -30% promo");
  assert.equal(freshOrderCents(MAX, PROMO), 66508, "Max, 36mo, -20% term, -30% promo");
});

