export async function adminExtendServer(prev: any, formData: FormData): Promise<{ error?: string }> {
  const admin = await requireAdmin();
  const serverId = String(formData.get("serverId") ?? "");
  const days = Number(formData.get("days"));
  if (!serverId || !Number.isFinite(days) || days === 0 || Math.abs(days) > 365) {
    return { error: "Days must be between -365 and 365." };
  }
  const server = await db.server.findUnique({ where: { id: serverId } });
  if (!server) return { error: "Server not found." };
  const base = server.expiresAt ? server.expiresAt.getTime() : Date.now();

  // ─── EXPIRESAT INTEGRITY ────────────────────────────────────────────────────
  // The whole proration model rests on "every month between now and `expiresAt` is
  // a month the customer has actually bought" (see lib/proration.ts
  // remainingMonths). This action moves `expiresAt` by up to a year per call, with
  // no call limit and no payment — so before the persisted rate existed, an admin
  // goodwill gift of 12 months was directly convertible to cash: downgrade the
  // gifted server and the prorated credit paid out real wallet money for months
  // nobody had ever been charged for. Admin-only, so never a self-service exploit,
  // but a support agent clicking "extend" was minting refundable balance.
  //
  // SEMANTICS CHOSEN: gifted months are recorded as sold at 100% off, and blended
  // into the rate the existing months are on. That is the honest reading of a gift
  // — those months cost the customer nothing, so nothing may prorate out of them —
  // and it is exact rather than blunt: the blend leaves the CASH VALUE of the
  // remaining window completely unchanged, so a customer who paid for 12 months and
  // was gifted a 13th still gets back precisely what those 12 paid months are worth
  // on a downgrade. Zeroing the whole term instead would confiscate what they paid;
  // leaving the rate alone is the money printer. Repeated gifts only ever dilute
  // toward 100, so no number of calls can raise the payout.
  //
  // A NEGATIVE `days` removes months rather than adding them, so there is nothing
  // to blend in: the customer keeps the rate they bought at over a shorter window,
  // which strictly reduces any future credit. Blending negative months would push
  // the rate the other way and over-credit what is left.
  const gifted = days > 0;
  const termPromoPercent = gifted
    ? prorateBlendPercent({
        currentPercent: resolveTermPromoPercent(server.termPromoPercent),
        currentMonths: remainingMonths(server.expiresAt, Date.now()),
        addedPercent: 100, // gifted: no cash changed hands for these months
        addedMonths: (days * 86400_000) / MS_PER_AVG_MONTH,
      })
    : resolveTermPromoPercent(server.termPromoPercent);

  await db.server.update({
    where: { id: serverId },
    data: { expiresAt: new Date(base + days * 86400_000), termPromoPercent },
  });
  await audit(
    admin.id,
    "admin.extend_server",
    `${serverId} ${days}d${gifted ? ` gifted (rate basis ${server.termPromoPercent ?? "null"}% -> ${termPromoPercent}% off)` : ""}`,
  );
  revalidatePath("/admin/subscriptions");
  return {};
}

